// AsUnaryOption converts a standard Option to a UnaryOption.
// This function is used to explicitly mark an option as suitable for unary RPC calls.
//
// Example:
//   opt := AsUnaryOption(WithTimeout(time.Second))
func AsUnaryOption(opt Option) UnaryOption {
	return UnaryOption{Option: opt}
}

// AsStreamOption converts a standard Option to a StreamOption.
// This function is used to explicitly mark an option as suitable for streaming RPC calls.
//
// Example:
//   opt := AsStreamOption(WithStreamMiddleware(myMiddleware))
func AsStreamOption(opt Option) StreamOption {
	return StreamOption{Option: opt}
}

