// UnaryOptions is a collection of UnaryOption values.
// It provides a convenient way to group multiple unary-specific options.
type UnaryOptions []UnaryOption

// ToOptions converts a UnaryOptions collection to a slice of standard Options.
func (opts UnaryOptions) ToOptions() []Option {
	result := make([]Option, len(opts))
	for i, opt := range opts {
		result[i] = opt.Option
	}
	return result
}

// StreamOptions is a collection of StreamOption values.
